json:
{
  "name": "actualites",
  "description": "Ouvre Google Actualités sur un sujet. Pour « quoi de neuf sur… », « les infos sur… ».",
  "parameters": [
    {
      "name": "sujet",
      "description": "Le sujet d'actualité",
      "required": true
    }
  ],
  "type": "open",
  "url": "https://news.google.com/search?q={sujet}&hl=fr&gl=FR&ceid=FR:fr"
}

{
  "name": "adresse_france",
  "description": "Retrouve une adresse postale en France avec son code postal et sa ville (source : Base Adresse Nationale, adresse.data.gouv.fr). Base d'adresses : les monuments et les commerces ne sont pas toujours reconnus, donner un numéro et une rue. Pour « c'est quel code postal au 10 rue de… ».",
  "parameters": [
    {
      "name": "recherche",
      "description": "Adresse, par exemple 10 rue de la paix Paris",
      "required": true
    }
  ],
  "type": "http",
  "url": "https://api-adresse.data.gouv.fr/search/?q={recherche}&limit=1",
  "result_path": "features.0.properties.label"
}

{
  "name": "agenda_evenement",
  "description": "Ouvre Google Agenda avec un nouvel événement prérempli (titre et lieu). L'utilisateur choisit la date et valide. Pour « ajoute un rendez-vous ».",
  "parameters": [
    {
      "name": "titre",
      "description": "Titre de l'événement",
      "required": true
    },
    {
      "name": "lieu",
      "description": "Lieu (facultatif)",
      "required": false
    }
  ],
  "type": "open",
  "url": "https://calendar.google.com/calendar/render?action=TEMPLATE&text={titre}&location={lieu}"
}

{
  "name": "anniversaires_celebres",
  "description": "Les personnalités nées un jour donné (Wikipédia). Pour « qui est né le même jour que moi ? », « quelles célébrités sont nées aujourd'hui ? ». Mois et jour sur deux chiffres.",
  "parameters": [
    {
      "name": "mois",
      "description": "Mois sur deux chiffres (01 à 12)",
      "required": true
    },
    {
      "name": "jour",
      "description": "Jour sur deux chiffres (01 à 31)",
      "required": true
    }
  ],
  "type": "http",
  "url": "https://api.wikimedia.org/feed/v1/wikipedia/fr/onthisday/births/{mois}/{jour}",
  "result_items": "births",
  "result_fields": [
    "year",
    "text"
  ],
  "result_max": 12
}

{
  "name": "archive_web",
  "description": "Donne le lien vers la copie la plus proche d'un site dans la Wayback Machine d'Internet Archive. Pour « à quoi ressemblait ce site avant », « ce site a disparu ».",
  "parameters": [
    {
      "name": "adresse",
      "description": "Adresse du site, par exemple example.com",
      "required": true
    }
  ],
  "type": "http",
  "url": "https://archive.org/wayback/available?url={adresse}",
  "result_path": "archived_snapshots.closest.url"
}

{
  "name": "bilan_telephone",
  "description": "Fait le point sur le téléphone : batterie, stockage libre et dernières notifications. À utiliser pour « comment va mon téléphone », « qu'est-ce que j'ai raté ».",
  "parameters": [],
  "type": "routine",
  "steps": [
    {
      "tool": "system_monitor",
      "args": {}
    },
    {
      "tool": "notifications",
      "args": {
        "limit": "5"
      }
    }
  ]
}

{
  "name": "carte_recherche",
